BEGIN;
CREATE SCHEMA stage4_test;
CREATE FUNCTION stage4_test.assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',message;END IF;END $$;
CREATE FUNCTION stage4_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected failure: %',statement;END $$;
GRANT USAGE ON SCHEMA stage4_test TO authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA stage4_test TO authenticated;
INSERT INTO auth.users(id,email) SELECT ('24000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'stage4-'||n||'@example.invalid' FROM generate_series(1,8)n;
INSERT INTO public.companies(id,nome,created_by) VALUES('14000000-0000-4000-8000-000000000001','Stage4','24000000-0000-4000-8000-000000000001'),('14000000-0000-4000-8000-000000000002','Other','24000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) SELECT '14000000-0000-4000-8000-000000000001',('24000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'auditor',(ARRAY['admin_empresa','analista_transporte','supervisor','operador_logistico','motorista','cliente','motorista','admin_geral'])[n],'24000000-0000-4000-8000-000000000001' FROM generate_series(1,8)n;
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual) VALUES('34000000-0000-4000-8000-000000000001','14000000-0000-4000-8000-000000000001','SG40001','caminhao','Stage4',1000),('34000000-0000-4000-8000-000000000002','14000000-0000-4000-8000-000000000001','SG40002','caminhao','Stage4',1000),('34000000-0000-4000-8000-000000000003','14000000-0000-4000-8000-000000000002','SG40003','caminhao','Stage4',1000);
INSERT INTO public.motoristas(id,company_id,nome,cnh,validade_cnh) VALUES('54000000-0000-4000-8000-000000000001','14000000-0000-4000-8000-000000000001','Driver fixture','12345678901','2030-01-01');
INSERT INTO public.maintenance_partners(id,company_id,razao_social,created_by) VALUES('44000000-0000-4000-8000-000000000001','14000000-0000-4000-8000-000000000001','Workshop fixture','24000000-0000-4000-8000-000000000001');
CREATE FUNCTION stage4_test.act(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER AS $$ SELECT public.maintenance_vehicle_command('14000000-0000-4000-8000-000000000001',action,payload); $$;
GRANT EXECUTE ON FUNCTION stage4_test.act(text,jsonb) TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000001',true);
SELECT stage4_test.act('preferences','{"vehicle_id":"34000000-0000-4000-8000-000000000001","default_partner_id":"44000000-0000-4000-8000-000000000001","preferred_partner_ids":["44000000-0000-4000-8000-000000000001"]}');
SELECT stage4_test.assert(stage4_test.act('dossier','{"vehicle_id":"34000000-0000-4000-8000-000000000001"}')->'preferences'->>'default_partner_id'='44000000-0000-4000-8000-000000000001','preferences persisted');
SELECT stage4_test.denied($q$SELECT stage4_test.act('dossier','{"vehicle_id":"34000000-0000-4000-8000-000000000003"}')$q$);
SELECT stage4_test.act('bind','{"vehicle_id":"34000000-0000-4000-8000-000000000001","driver_id":"54000000-0000-4000-8000-000000000001","user_id":"24000000-0000-4000-8000-000000000005"}');
SELECT set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000005',true);
SELECT stage4_test.assert(stage4_test.act('driver')->'vehicle'->>'placa'='SG40001','driver sees assigned vehicle');
SELECT stage4_test.denied($q$SELECT stage4_test.act('dossier','{"vehicle_id":"34000000-0000-4000-8000-000000000002"}')$q$);
SELECT stage4_test.denied($q$SELECT stage4_test.act('options')$q$);
SELECT stage4_test.denied($q$SELECT stage4_test.act('occurrences')$q$);
SELECT set_config('stage4_test.occ',(stage4_test.act('report','{"vehicle_id":"34000000-0000-4000-8000-000000000002","tipo":"quebra","gravidade":"grave","descricao":"Freio com falha","latitude":-23.5,"longitude":-46.6}')->>'id'),true);
RESET ROLE;
SELECT stage4_test.assert((SELECT vehicle_id='34000000-0000-4000-8000-000000000001' AND driver_id='54000000-0000-4000-8000-000000000001' AND created_by='24000000-0000-4000-8000-000000000005' FROM public.vehicle_occurrences WHERE id=current_setting('stage4_test.occ')::uuid),'driver vehicle and author derived on server');
SET LOCAL ROLE authenticated;
SELECT stage4_test.assert((SELECT count(*)=0 FROM public.veiculos),'driver cannot query legacy fleet directly');
SELECT stage4_test.assert((SELECT count(*)=0 FROM public.motoristas),'driver cannot query legacy driver registry');
SELECT stage4_test.assert(NOT has_table_privilege('authenticated','public.vehicle_occurrences','INSERT'),'direct occurrence write denied');
SELECT stage4_test.assert(NOT has_table_privilege('authenticated','public.maintenance_vehicle_events','DELETE'),'immutable ledger');
SELECT stage4_test.assert((SELECT count(*)=0 FROM public.maintenance_vehicle_events),'driver cannot read ledger');
SELECT stage4_test.assert(maintenance_private.storage_access('14000000-0000-4000-8000-000000000001/occurrences/'||current_setting('stage4_test.occ')||'/photo.jpg',true),'driver can upload own photo');
INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('maintenance','14000000-0000-4000-8000-000000000001/occurrences/'||current_setting('stage4_test.occ')||'/photo.jpg','{"mimetype":"image/jpeg"}');
SELECT stage4_test.act('photo_add',jsonb_build_object('id',current_setting('stage4_test.occ'),'path','14000000-0000-4000-8000-000000000001/occurrences/'||current_setting('stage4_test.occ')||'/photo.jpg'));
WITH removed AS(DELETE FROM storage.objects WHERE name LIKE '%/photo.jpg' RETURNING *) SELECT stage4_test.assert(count(*)=0,'driver cannot delete evidence') FROM removed;
SELECT set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000007',true);
SELECT stage4_test.assert(stage4_test.act('driver')->'vehicle'='null'::jsonb,'unbound driver sees no vehicle');
SELECT stage4_test.assert(NOT maintenance_private.storage_access('14000000-0000-4000-8000-000000000001/occurrences/'||current_setting('stage4_test.occ')||'/photo.jpg',true),'another driver denied photo');
SELECT set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000004',true);
SELECT stage4_test.act('report','{"vehicle_id":"34000000-0000-4000-8000-000000000002","tipo":"pneu","gravidade":"leve","descricao":"Pneu furado"}');
SELECT stage4_test.denied($q$SELECT stage4_test.act('preferences','{"vehicle_id":"34000000-0000-4000-8000-000000000001"}')$q$);
SELECT stage4_test.denied($q$SELECT stage4_test.act('from_occurrence',jsonb_build_object('id',current_setting('stage4_test.occ'),'order','{}'::jsonb))$q$);
SELECT stage4_test.act('dossier','{"vehicle_id":"34000000-0000-4000-8000-000000000001"}');
SELECT set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000003',true);
SELECT stage4_test.act('report','{"vehicle_id":"34000000-0000-4000-8000-000000000002","tipo":"outros","gravidade":"leve","descricao":"Inspeção diária"}');
SELECT stage4_test.denied($q$SELECT stage4_test.act('bind','{"vehicle_id":"34000000-0000-4000-8000-000000000001"}')$q$);
SELECT set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000006',true);
SELECT stage4_test.denied($q$SELECT stage4_test.act('options')$q$);
SELECT set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000002',true);
SELECT set_config('stage4_test.os',(stage4_test.act('from_occurrence',jsonb_build_object('id',current_setting('stage4_test.occ'),'order','{"partner_id":"44000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"alta","descricao_problema":"Freio com falha","km_abertura":1000}'::jsonb))->>'id'),true);
SELECT stage4_test.assert((SELECT order_id=current_setting('stage4_test.os')::uuid FROM public.vehicle_occurrences WHERE id=current_setting('stage4_test.occ')::uuid),'OS linked atomically');
SELECT stage4_test.denied($q$SELECT stage4_test.act('from_occurrence',jsonb_build_object('id',current_setting('stage4_test.occ'),'order','{}'::jsonb))$q$);
SELECT stage4_test.assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(stage4_test.act('available')) t WHERE t->>'placa'='SG40001'),'maintenance vehicle excluded');
SELECT stage4_test.denied($q$SELECT stage4_test.act('allocate','{"vehicle_id":"34000000-0000-4000-8000-000000000001","kind":"trip","reference":"blocked"}')$q$);
SELECT stage4_test.act('allocate','{"vehicle_id":"34000000-0000-4000-8000-000000000002","kind":"trip","reference":"trip-1"}');
SELECT stage4_test.denied($q$SELECT public.maintenance_order_command('14000000-0000-4000-8000-000000000001','create','{"vehicle_id":"34000000-0000-4000-8000-000000000002","partner_id":"44000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"alta","descricao_problema":"Pending trip","km_abertura":1000}')$q$);
SELECT stage4_test.act('release','{"vehicle_id":"34000000-0000-4000-8000-000000000002","kind":"trip","reference":"trip-1"}');
SELECT stage4_test.assert(jsonb_array_length(stage4_test.act('events','{"vehicle_id":"34000000-0000-4000-8000-000000000001"}'))>=4,'permanent history contains preferences, binding, report and order');
SELECT stage4_test.assert(NOT has_function_privilege('anon','public.maintenance_vehicle_command(uuid,text,jsonb)','EXECUTE'),'anonymous RPC denied');
ROLLBACK;
